package me.matsumo.fanbox.core.logs.category

import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.buildJsonObject
import kotlinx.serialization.json.put

// This class is automatically generated by generate-log-classes.
sealed interface ReviewsLog : LogCategory {

    class RequestReview internal constructor(isSuccess: Boolean) : ReviewsLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "reviews")
            put("event_name", "request_review")
            put("is_success", isSuccess)
        }
    }

    class TryRequestReview internal constructor(isEligible: Boolean) : ReviewsLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "reviews")
            put("event_name", "try_request_review")
            put("is_eligible", isEligible)
        }
    }

    class Reviewed internal constructor() : ReviewsLog {
        override val properties: JsonObject = buildJsonObject {
            put("event_category", "reviews")
            put("event_name", "reviewed")
        }
    }

    companion object {
        // Google Play のアプリ内レビューで requestReviewFlow の結果が返ったときのログ。成功したときだけ launchReviewFlow に進む
        fun requestReview(isSuccess: Boolean) = RequestReview(isSuccess)

        // レビュー依頼の発火条件に到達したときのログ。ダウンロード予約が空から空でない状態に変わったときに 1 回送る
        fun tryRequestReview(isEligible: Boolean) = TryRequestReview(isEligible)

        // launchReviewFlow が完了したときのログ。API はレビューの有無を返さないため、ユーザーがレビューを書いたことは表さない
        fun reviewed() = Reviewed()
    }
}
